      SUBROUTINE LINEC---- DEFINE A BEAM LINEC-----------------------------------------------------------------------      INCLUDE 'DATUM.CIN'      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'LBDAT.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCARD.CIN'      INCLUDE 'RDCHAR.CIN'      INCLUDE 'RDWRDS.CIN'C-----------------------------------------------------------------------      CHARACTER*15    KNAME      LOGICAL         FLAG      EQUIVALENCE     (FAKE,LAKE)C-----------------------------------------------------------------------C---- COMMA?C      IF (LBDAT .NE. BLANK) GO TO 100      CALL RDNEXT      IF (ENDFIL) GO TO 800      IF (ITEM .EQ. COMMA) THEN        CALL RDNEXT        IF (ENDFIL) GO TO 800      ENDIFCC---- BEAM LINE NAMEC      CALL RDWORD(KNAME,LNAME)      IF (LNAME .EQ. 0) THEN        CALL RDFAIL        WRITE (IECHO,910)        GO TO 800      ENDIF      LBDAT = KNAME  100 JDEF = 1      NDESC = 1      NWORD = 2      LAKE = 24      DATUM(1) = FAKE      LAKE = JDEF      DATUM(2) = FAKE      LABLE = LBDAT      CALL ELSTORCC---- FORMAL ARGUMENT LISTC      CALL RDNEXT      IF (ENDFIL) GO TO 800      IF (ITEM .EQ. '(') THEN        CALL DECFRM        IF (ENDFIL) GO TO 800        FLAG = ERROR        IF (FLAG) GO TO 800      ENDIFCC---- EQUALS SIGN?C      CALL RDTEST('=',FLAG)      IF (FLAG) GO TO 800CC---- BEAM LINE LISTC      CALL DECLST      FLAG = ERROR      IF (ENDFIL .OR. FLAG) GO TO 800CC---- END OF COMMAND?C      CALL RDNEXT      IF (ENDFIL) GO TO 800      CALL RDTEST(';',FLAG)      IF (FLAG) GO TO 800CC---- STORE DEFINITIONC      JDEF = 2      NDESC = 1      NWORD = 2      LAKE = 24      DATUM(1) = FAKE      LAKE = JDEF      DATUM(2) = FAKE      LABLE = LBDAT      CALL ELSTOR      GO TO 900CC---- ERROR EXIT --- LEAVE BEAM LINE UNDEFINEDC  800 ERROR = .TRUE.  900 RETURNC-----------------------------------------------------------------------  910 FORMAT(' *** ERROR *** BEAM LINE NAME EXPECTED'/' ')  920 FORMAT(' ** WARNING ** THE ABOVE NAME WAS DEFINED IN LINE ',I5,     +       ', IT WILL BE REDEFINED'/' ')C-----------------------------------------------------------------------      END